svg.script:
(function () {
  const svg = document.getElementById('fourierViz');

  // Harmonic coefficients picked to create sharper features than a single sine.
  const A = [1.00, 0.55, 0.38, 0.30, 0.23, 0.18, 0.13];
  const phi = [0.10, 1.30, -0.90, 2.20, -1.65, 0.65, -2.35];

  const paths = [
    document.getElementById('c1'),
    document.getElementById('c2'),
    document.getElementById('c3'),
    document.getElementById('c4'),
    document.getElementById('c5'),
    document.getElementById('c6'),
    document.getElementById('c7')
  ];
  const complexPath = document.getElementById('complexPath');

  const partialSumDots = document.getElementById('partialSumDots');
  const componentDots = document.getElementById('componentDots');
  const connections = document.getElementById('connections');
  const componentLabels = document.getElementById('componentLabels');

  const barsG = document.getElementById('bars');
  const phaseG = document.getElementById('phaseSpectrum');

  // Layout constants (keep in sync with SVG geometry)
  const leftPlot = { x: 70, y: 120, w: 350, h: 560, yRange: 3.0 }; // axis origin at x=70
  const midPlot = { x: 515, y: 120, w: 380, h: 68, gap: 12, yRange: 1.15 };

  // x spans two periods: 0..4π
  const X0 = 0;
  const X1 = 4 * Math.PI;
  const probeTheta = 2 * Math.PI;

  function mapX(plot, theta) {
    const u = (theta - X0) / (X1 - X0);
    return plot.x + (10 + u * (plot.w - 20));
  }
  function mapY(plot, y) {
    const cy = plot.y + plot.h / 2;
    const s = (plot.h * 0.45) / plot.yRange;
    return cy - y * s;
  }

  function dFromFunc(plot, fn, samples = 680) {
    let d = '';
    for (let i = 0; i <= samples; i++) {
      const theta = X0 + (i / samples) * (X1 - X0);
      const x = mapX(plot, theta);
      const y = mapY(plot, fn(theta));
      d += (i === 0 ? 'M ' : ' L ') + x.toFixed(2) + ' ' + y.toFixed(2);
    }
    return d;
  }

  function sumAt(theta, t) {
    let s = 0;
    for (let n = 1; n <= 7; n++) {
      s += A[n - 1] * Math.sin(n * theta + phi[n - 1] + n * t);
    }
    return s;
  }

  function componentAt(n, theta, t) {
    return A[n - 1] * Math.sin(n * theta + phi[n - 1] + n * t);
  }

  function readTimeFromCSS() {
    const raw = getComputedStyle(svg).getPropertyValue('--t');
    const v = parseFloat(raw);
    if (Number.isFinite(v)) return v;
    // Fallback if typed property not supported
    const now = (performance && performance.now ? performance.now() : Date.now());
    return (now / 1000) * (2 * Math.PI / 6.5);
  }

  // Static: bar chart and labels
  function initStatic() {
    // Component labels (A_n)
    const labelYs = Array.from({ length: 7 }, (_, i) => midPlot.y + i * (midPlot.h + midPlot.gap) + 18);
    const labelX = midPlot.x + midPlot.w - 10;
    componentLabels.innerHTML = '';
    for (let i = 0; i < 7; i++) {
      const y = labelYs[i];
      const txt = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      txt.setAttribute('x', labelX);
      txt.setAttribute('y', y);
      txt.setAttribute('text-anchor', 'end');
      txt.setAttribute('class', 'tickText mono');
      txt.textContent = `A${i + 1}=${A[i].toFixed(2)}`;
      componentLabels.appendChild(txt);
    }

    // Magnitude spectrum bars (static magnitudes)
    barsG.innerHTML = '';
    const maxA = Math.max(...A);
    const baseY = 230;
    const chartH = 190;
    const chartX0 = 55;
    const barW = 36;
    const gap = 10;
    for (let i = 0; i < 7; i++) {
      const x = chartX0 + i * (barW + gap);
      const h = (A[i] / maxA) * chartH;
      const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      rect.setAttribute('x', x);
      rect.setAttribute('y', (baseY - h).toFixed(2));
      rect.setAttribute('width', barW);
      rect.setAttribute('height', h.toFixed(2));
      rect.setAttribute('rx', '4');
      rect.setAttribute('class', 'bar');
      barsG.appendChild(rect);

      const lbl = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      lbl.setAttribute('x', x + barW / 2);
      lbl.setAttribute('y', 250);
      lbl.setAttribute('text-anchor', 'middle');
      lbl.setAttribute('class', 'barLabel');
      lbl.textContent = `${i + 1}f`;
      barsG.appendChild(lbl);
    }

    // Phase spectrum placeholders
    // 7 circles in a row, hands updated in animation loop
    phaseG.innerHTML = '';
    const px0 = 35;
    const py0 = 35;
    const cellW = 52;
    const r = 18;
    for (let i = 0; i < 7; i++) {
      const cx = px0 + i * cellW + r;
      const cy = py0 + r;

      const label = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      label.setAttribute('x', cx);
      label.setAttribute('y', cy + 42);
      label.setAttribute('text-anchor', 'middle');
      label.setAttribute('class', 'tickText');
      label.textContent = `${i + 1}f`;
      phaseG.appendChild(label);

      const c = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      c.setAttribute('cx', cx);
      c.setAttribute('cy', cy);
      c.setAttribute('r', r);
      c.setAttribute('class', 'phaseCircle');
      phaseG.appendChild(c);

      const hand = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      hand.setAttribute('x1', cx);
      hand.setAttribute('y1', cy);
      hand.setAttribute('x2', cx);
      hand.setAttribute('y2', cy - r + 3);
      hand.setAttribute('class', 'phaseHand');
      hand.setAttribute('data-n', String(i + 1));
      hand.setAttribute('id', `phaseHand${i + 1}`);
      phaseG.appendChild(hand);

      const center = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      center.setAttribute('cx', cx);
      center.setAttribute('cy', cy);
      center.setAttribute('r', 2.4);
      center.setAttribute('fill', 'rgba(15,23,42,0.85)');
      phaseG.appendChild(center);
    }

    const note = document.createElementNS('http://www.w3.org/2000/svg', 'text');
    note.setAttribute('x', 20);
    note.setAttribute('y', 160);
    note.setAttribute('class', 'formulaNote');
    note.textContent = 'hands show instantaneous phase: φₙ + n·t';
    phaseG.appendChild(note);
  }

  function update(t) {
    // Update component paths
    for (let i = 0; i < 7; i++) {
      const n = i + 1;
      const plot = {
        x: midPlot.x,
        y: midPlot.y + i * (midPlot.h + midPlot.gap),
        w: midPlot.w,
        h: midPlot.h,
        yRange: midPlot.yRange
      };
      paths[i].setAttribute('d', dFromFunc(plot, (theta) => componentAt(n, theta, t), 420));
    }

    // Update complex wave path
    complexPath.setAttribute('d', dFromFunc(leftPlot, (theta) => sumAt(theta, t), 740));

    // Probe dots + partial sums at θ=2π
    const probeXLeft = mapX(leftPlot, probeTheta);
    const sumY = sumAt(probeTheta, t);

    // Build partial sums and connecting lines
    partialSumDots.innerHTML = '';
    componentDots.innerHTML = '';
    connections.innerHTML = '';

    let running = 0;
    const colors = ['harm1','harm2','harm3','harm4','harm5','harm6','harm7'];
    for (let i = 0; i < 7; i++) {
      const n = i + 1;
      const cY = componentAt(n, probeTheta, t);
      running += cY;

      // Dot in component plot
      const plotY0 = midPlot.y + i * (midPlot.h + midPlot.gap);
      const compPlot = { x: midPlot.x, y: plotY0, w: midPlot.w, h: midPlot.h, yRange: midPlot.yRange };
      const probeXMid = mapX(compPlot, probeTheta);
      const probeYMid = mapY(compPlot, cY);

      const dotC = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      dotC.setAttribute('cx', probeXMid);
      dotC.setAttribute('cy', probeYMid);
      dotC.setAttribute('r', 3.6);
      dotC.setAttribute('class', `dot ${colors[i]}`);
      dotC.setAttribute('fill', 'white');
      componentDots.appendChild(dotC);

      const dotCfill = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      dotCfill.setAttribute('cx', probeXMid);
      dotCfill.setAttribute('cy', probeYMid);
      dotCfill.setAttribute('r', 1.8);
      dotCfill.setAttribute('class', colors[i]);
      dotCfill.setAttribute('fill', 'currentColor');
      // currentColor isn't inherited for SVG elements consistently; set explicit fill.
      dotCfill.setAttribute('fill', ['#2563EB','#7C3AED','#DB2777','#F97316','#10B981','#14B8A6','#64748B'][i]);
      componentDots.appendChild(dotCfill);

      // Partial sum dot on complex wave
      const probeYLeft = mapY(leftPlot, running);
      const dotS = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      dotS.setAttribute('cx', probeXLeft);
      dotS.setAttribute('cy', probeYLeft);
      dotS.setAttribute('r', 4.0);
      dotS.setAttribute('class', `dot ${colors[i]}`);
      dotS.setAttribute('fill', 'rgba(255,255,255,0.95)');
      partialSumDots.appendChild(dotS);

      const dotSfill = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      dotSfill.setAttribute('cx', probeXLeft);
      dotSfill.setAttribute('cy', probeYLeft);
      dotSfill.setAttribute('r', 2.1);
      dotSfill.setAttribute('fill', ['#2563EB','#7C3AED','#DB2777','#F97316','#10B981','#14B8A6','#64748B'][i]);
      partialSumDots.appendChild(dotSfill);

      // Connection line from component dot to partial sum dot
      const line = document.createElementNS('http://www.w3.org/2000/svg', 'path');
      const midX = (probeXMid + probeXLeft) / 2;
      const d = `M ${probeXMid.toFixed(2)} ${probeYMid.toFixed(2)} C ${midX.toFixed(2)} ${(probeYMid).toFixed(2)}, ${midX.toFixed(2)} ${(probeYLeft).toFixed(2)}, ${probeXLeft.toFixed(2)} ${probeYLeft.toFixed(2)}`;
      line.setAttribute('d', d);
      line.setAttribute('class', `connLine ${colors[i]}`);
      line.setAttribute('fill', 'none');
      connections.appendChild(line);
    }

    // Final sum dot (dark) at probe
    const finalDot = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    finalDot.setAttribute('cx', probeXLeft);
    finalDot.setAttribute('cy', mapY(leftPlot, sumY));
    finalDot.setAttribute('r', 5.2);
    finalDot.setAttribute('class', 'dot dotSum');
    partialSumDots.appendChild(finalDot);

    // Update phase hands (φ_n + n·t)
    for (let i = 0; i < 7; i++) {
      const n = i + 1;
      const angle = (phi[i] + n * t); // radians
      const hand = document.getElementById(`phaseHand${n}`);
      if (!hand) continue;

      const x1 = parseFloat(hand.getAttribute('x1'));
      const y1 = parseFloat(hand.getAttribute('y1'));
      // Hand line goes to y2; rotate around center (x1,y1)
      const deg = (angle * 180) / Math.PI;
      hand.setAttribute('transform', `rotate(${deg.toFixed(2)} ${x1} ${y1})`);
    }
  }

  function frame() {
    const t = readTimeFromCSS();
    update(t);
    requestAnimationFrame(frame);
  }

  initStatic();
  requestAnimationFrame(frame);
})();
